import { useEffect, useState } from 'react';
import { MessageSquareReply, Star } from 'lucide-react';
import { vendorAPI } from '../../services/api';
import Loader from '../../components/common/Loader';
import toast from 'react-hot-toast';

export default function VendorReviewsPage() {
  const [status, setStatus] = useState('');
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [drafts, setDrafts] = useState({});
  const load = () => { setLoading(true); vendorAPI.getReviews({ status, limit: 50 }).then(response => setData(response.data || null)).catch(error => toast.error(error.message || 'Could not load reviews')).finally(() => setLoading(false)); };
  useEffect(load, [status]);
  const saveReply = async review => { try { await vendorAPI.replyToReview(review._id, { reply: drafts[review._id] ?? review.vendorReply ?? '' }); toast.success('Reply saved'); load(); } catch (error) { toast.error(error.message || 'Could not save reply'); } };
  if (loading) return <div className="flex justify-center py-16"><Loader /></div>;
  const stats = data?.stats || {};
  return <div className="mx-auto max-w-6xl space-y-6" data-testid="vendor-reviews-page">
    <header className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-rose-600">Seller reputation</p><h1 className="mt-2 text-2xl font-bold text-gray-900">Product reviews</h1><p className="mt-1 text-sm text-gray-500">Read reviews for your products and reply to customers.</p></div><select data-testid="vendor-review-status" value={status} onChange={event => setStatus(event.target.value)} className="rounded-xl border border-gray-200 bg-white px-3 py-2 text-sm"><option value="">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></header>
    <div className="grid gap-4 sm:grid-cols-3"><div className="rounded-2xl bg-amber-50 p-5"><p className="text-xs font-semibold uppercase tracking-wide text-gray-500">Average rating</p><p className="mt-2 flex items-center gap-2 text-2xl font-bold text-gray-900"><Star className="fill-amber-400 text-amber-400" size={20} />{Number(stats.average || 0).toFixed(1)}</p></div><div className="rounded-2xl bg-indigo-50 p-5"><p className="text-xs font-semibold uppercase tracking-wide text-gray-500">Total reviews</p><p className="mt-2 text-2xl font-bold text-gray-900">{stats.total || 0}</p></div><div className="rounded-2xl bg-blue-50 p-5"><p className="text-xs font-semibold uppercase tracking-wide text-gray-500">Awaiting moderation</p><p className="mt-2 text-2xl font-bold text-gray-900">{stats.pending || 0}</p></div></div>
    <section className="space-y-4">{(data?.reviews || []).map(review => <article key={review._id} className="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-bold text-gray-900">{review.product?.title || 'Product'}</p><p className="mt-1 text-xs text-gray-400">{review.user?.name || review.user?.email || 'Customer'} · {new Date(review.createdAt).toLocaleDateString()}</p></div><div className="flex items-center gap-1 text-sm font-semibold text-amber-600">{[1, 2, 3, 4, 5].map(value => <Star key={value} size={15} className={value <= review.rating ? 'fill-amber-400 text-amber-400' : 'text-gray-300'} />)}<span className="ml-1 rounded-full bg-gray-100 px-2 py-1 text-xs capitalize text-gray-600">{review.status}</span></div></div><h2 className="mt-4 font-semibold text-gray-800">{review.title || 'Customer review'}</h2><p className="mt-1 text-sm leading-6 text-gray-600">{review.comment}</p><div className="mt-4 flex gap-2"><MessageSquareReply size={16} className="mt-2 text-indigo-500" /><textarea value={drafts[review._id] ?? review.vendorReply ?? ''} onChange={event => setDrafts(current => ({ ...current, [review._id]: event.target.value }))} maxLength="2000" rows="2" placeholder="Reply to this customer…" className="min-w-0 flex-1 rounded-xl border border-gray-200 px-3 py-2 text-sm outline-none focus:border-indigo-400" /><button type="button" onClick={() => saveReply(review)} className="self-end rounded-xl bg-indigo-600 px-3 py-2 text-sm font-semibold text-white">Save reply</button></div>{review.adminReply && <p className="mt-3 rounded-xl bg-gray-50 p-3 text-xs text-gray-500">Admin response: {review.adminReply}</p>}</article>)}{!data?.reviews?.length && <div className="rounded-2xl border border-dashed border-gray-300 p-12 text-center text-sm text-gray-400">No reviews found for your products.</div>}</section>
  </div>;
}
